  band: SV('<ellipse cx="12" cy="10" rx="8" ry="4.5"/><path d="M4.5 12.5c1.6 3 4.3 4.5 7.5 4.5s5.9-1.5 7.5-4.5"/>'),
  other: SV('<circle cx="12" cy="12" r="7.5"/><path d="M4.5 12h15M12 4.5c3 3 3 12 0 15"/>'),
