// ---- default sets × reps by kind (the coach can change every number before adding)
const KIND = { c: [4, '8'], a: [3, '10'], i: [3, '12'], e: [3, '15'], h: [3, '30 s'], t: [1, '20 min'], x: [4, '30 s'], s: [2, '30 s'], m: [2, '10'], f: [1, '60 s'], w: [3, '30 m'] };
export function defaultsFor(x) { const k = KIND[(x && x.kind) || ''] || [3, '10']; return { sets: k[0], reps: k[1] }; }

// ---- which lists an exercise shows in: its own group.sub plus the "also" ones
export function listsOf(x) { const own = x.grp ? [x.grp + '.' + x.sub] : []; return own.concat(String(x.also || '').split(',').map(s => s.trim()).filter(Boolean)); }
export function inGroup(x, g, s) { return listsOf(x).some(k => k === g + '.' + s || (!s && k.split('.')[0] === g)); }
export function exLine(x) {   // "Upper chest · Dumbbell" — the coach's own exercises without a group show their muscle text
  const parts = x.grp ? [subName(x.grp, x.sub, true), equipName(x.equip)] : [LANG.cur === 'ka' && x.muscle_ka ? x.muscle_ka : x.muscle];
  return parts.filter(Boolean).join(' · ');
}
// a "How to" link for every library exercise: the coach's own video if there is one, otherwise a YouTube search
export function howUrl(x) {
  if (!x) return '';
  if (x.video_url) return x.video_url;
  return x.owner_id ? '' : 'https://www.youtube.com/results?search_query=' + encodeURIComponent(x.name + ' exercise form');
}

// ---- search: name (EN + KA), search words, group / part / equipment names, in both languages
function norm(s) { return String(s || '').toLowerCase().replace(/[-–'’“”„()]/g, ' ').replace(/\s+/g, ' ').trim(); }
export function searchEx(list, q) {
  const words = norm(q).split(' ').filter(Boolean); if (!words.length) return list.slice();
  const scored = [];
  for (const x of list) {
    const names = norm(x.name + ' ' + (x.name_ka || '')), extra = norm([x.tags, x.muscle, x.muscle_ka, x.grp ? groupName(x.grp) + ' ' + subName(x.grp, x.sub, true) : '', equipName(x.equip)].join(' '));
    let s = 0, ok = true;
    for (const w of words) {
      if ((' ' + names).includes(' ' + w)) s += 6; else if (names.includes(w)) s += 4; else if ((' ' + extra).includes(' ' + w)) s += 2; else if (extra.includes(w)) s += 1; else { ok = false; break; }
    }
    if (ok) scored.push([s + (x.pop ? 0.5 : 0) + (x.owner_id ? 0.7 : 0), x]);
  }
  return scored.sort((a, b) => b[0] - a[0] || (a[1].pop || 999) - (b[1].pop || 999)).map(p => p[1]);
}
// a stable order inside a list: popular first (by rank), then the library order, the coach's own at the end
export function byOrder(a, b) { return (a.owner_id ? 1 : 0) - (b.owner_id ? 1 : 0) || (a.pop || 999) - (b.pop || 999) || (a.pos || 999) - (b.pos || 999) || a.name.localeCompare(b.name); }

// ---- the body figure: front and back, a calm drawing (not anatomy). Paths are the figure's right half; the left half
// is the same paths mirrored. Each muscle region has a key; a group/part lights up its regions in coral.
const FRONT = {
  traps: 'M45 27 L45 32 L36 34 C39 31 42 29 45 27 Z',
  dside: 'M34 33 C28 34 25 39 25 46 L28 51 C28 44 30 38 34 33 Z',
  dfront: 'M35.2 32.6 C31 37 29 43 29 51 L33 52 L38.2 43 L39.4 34 Z',
  chest: 'M49.4 34 L40.6 34 L39.3 43 L35.6 50 C40 54.6 45 55.2 49.4 53.2 Z',
  biceps: 'M28 53 L34 54 C35 60 34.2 67 32.6 73 L27 72 C25.6 66 26 59 28 53 Z',
  forearm: 'M27 75 L32.6 75.5 C32.6 83 31.6 90 30.6 97 L26.6 97 C25 90 25 82 27 75 Z',
  obl: 'M37 56.4 L43.4 57.4 L43.4 84.5 L39.6 86 C38 79 36.6 68 37 56.4 Z',
  absup: 'M44.6 57 L49.4 57 L49.4 70.4 L44.6 70.4 Z',
  abslow: 'M44.6 72 L49.4 72 L49.4 88 L44.6 85.6 Z',
  quads: 'M38.6 98 C36.4 109 37 124 39.6 138 L46 138 C47.4 126 47.8 112 46.8 100.5 Z',
  add: 'M47.8 100.2 L49.2 100.8 L49 121 C48.2 114 47.9 107 47.8 100.2 Z',
};
const FRONT_N = {   // not muscles the picker names: hands, shins, feet, hips
  hand: 'M26.4 99 L30.8 99 L31 104.5 C30 107 27.4 107 26.4 104.5 Z',
  hip: 'M39.8 87.4 L49.4 89.6 L49.4 99 L46.6 99.4 C44 98 41 97.2 38.8 96.6 Z',
  shin: 'M39.6 143.6 C38.6 155 39.4 168 41 178 L45.6 178 C46.6 168 47 155 46 143.6 Z',
  foot: 'M40.6 180 L45.8 180 L46.4 186 L38.4 186 C38.4 183.4 39.4 181.4 40.6 180 Z',
};
const BACK = {
  traps: 'M50 25 L45 26 C42 29 39 31 36 33.5 L44 38 L50 50 Z',
  dside: FRONT.dside,
  drear: 'M35.2 32.6 C31 37 29 43 29 51 L33 52 L37.4 41.5 L36.4 34.2 Z',
  upper: 'M37.4 35.4 L44 38.6 L48.8 49.4 L41 50.4 L37.6 44 Z',
  cuff: 'M38.4 39.6 C39.6 38.4 42 38.6 43 40.2 C43.4 42 42 43.6 40.4 43.4 C38.8 43.2 38 41.2 38.4 39.6 Z',
  lats: 'M36.6 45.6 L41 52 L48.8 52.4 L48.8 61.6 L44.4 70 C40.4 64 36.8 56.6 36.4 50.4 Z',
  lower: 'M45.6 64.4 L49.4 58.4 L49.4 86 L45.6 86 Z',
  triceps: FRONT.biceps,
  forearm: FRONT.forearm,
  abd: 'M38.2 86.2 L43 86.2 C41 89 39.6 93 38.6 97 C37.6 93 37.6 89.4 38.2 86.2 Z',
  glutes: 'M43.6 86.2 L49.4 87.2 L49.4 104.4 C45 106.2 40.4 104.4 38.8 98.6 C39.8 92.6 41.2 89.2 43.6 86.2 Z',
  hams: 'M38.8 103.6 C37 114 38 126 39.6 138 L46 138 C47.4 126 48.4 114 48.6 106.4 C45 107.8 41.6 106.8 38.8 103.6 Z',
  calves: 'M39.6 145 C37.6 152 37.8 160 40.6 170 L45 172 C47 163 47.6 153 46 145 Z',
};
const BACK_N = {
  hand: FRONT_N.hand,
  waist: 'M37.8 58 C38.2 70 38.6 79 39.4 86 L45 86 L45 70.4 L44.4 70.4 Z',
  heel: 'M40.8 172.4 L45 173.4 L45.8 186 L39.4 186 C39.4 181 40 176 40.8 172.4 Z',
};
// group.sub → [view, region] pairs
const REG = {
  'chest.upper': [['f', 'chest@u']], 'chest.mid': [['f', 'chest@m']], 'chest.lower': [['f', 'chest@l']],
  'back.lats': [['b', 'lats']], 'back.upper': [['b', 'upper']], 'back.traps': [['b', 'traps'], ['f', 'traps']], 'back.lower': [['b', 'lower']],
  'legs.quads': [['f', 'quads']], 'legs.hams': [['b', 'hams']], 'legs.glutes': [['b', 'glutes']], 'legs.calves': [['b', 'calves']], 'legs.hips': [['f', 'add'], ['b', 'abd']],
  'shoulders.front': [['f', 'dfront']], 'shoulders.side': [['f', 'dside'], ['b', 'dside']], 'shoulders.rear': [['b', 'drear']], 'shoulders.cuff': [['b', 'cuff']],
  'triceps.ext': [['b', 'triceps']], 'triceps.pushdown': [['b', 'triceps']], 'triceps.press': [['b', 'triceps']],
  'biceps.biceps': [['f', 'biceps']], 'biceps.forearms': [['f', 'forearm'], ['b', 'forearm']],
  'abs.crunch': [['f', 'absup']], 'abs.lower': [['f', 'abslow']], 'abs.obliques': [['f', 'obl']], 'abs.stab': [['f', 'absup'], ['f', 'abslow'], ['f', 'obl'], ['b', 'lower']],
};
// which views a group's page shows
export function viewsOf(g) { return { chest: 'f', back: 'b', legs: 'fb', shoulders: 'fb', triceps: 'b', biceps: 'f', abs: 'f' }[g] || 'f'; }
// hot regions for a set of group.sub keys: level 2 = these, level 1 = the rest of their groups (context)
export function hotFor(keys, soft) {
  const H = { f: {}, b: {} };
  (soft || []).forEach(k => (REG[k] || []).forEach(([v, r]) => { H[v][r] = Math.max(H[v][r] || 0, 1); }));
  (keys || []).forEach(k => (REG[k] || []).forEach(([v, r]) => { H[v][r] = 2; }));
  return H;
}
let figN = 0;
// one view of the figure. hot = {region: 1|2}; mode 'joints' (mobility) puts slate dots on the joints, 'heart' (cardio)
// an orange heart on the chest, 'all' (full body) lights everything softly.
export function figure(view, hot, opts) {
  opts = opts || {}; const id = 'fg' + (++figN); hot = hot || {};
  const R = view === 'b' ? BACK : FRONT, N = view === 'b' ? BACK_N : FRONT_N;
  const lvl = k => opts.mode === 'all' ? Math.max(1, hot[k] || 0) : (hot[k] || 0);
  const half = (mirror) => {
    let s = '';
    for (const k in N) s += '<path class="nz" d="' + N[k] + '"/>';
    for (const k in R) {
      if (k === 'chest') {   // the chest is one shape cut into three bands: upper / middle / lower
        [['u', 33, 41.4], ['m', 41.4, 47.6], ['l', 47.6, 56]].forEach(([b, y0, y1]) => { s += '<path class="mz l' + lvl('chest@' + b) + '" data-k="chest@' + b + '" clip-path="url(#' + id + b + ')" d="' + R.chest + '"/>'; });
      } else if (k !== 'cuff' || lvl(k)) s += '<path class="mz l' + lvl(k) + '" data-k="' + k + '" d="' + R[k] + '"/>';
    }
    return mirror ? '<g transform="matrix(-1 0 0 1 100 0)">' + s + '</g>' : s;
  };
  const clips = view === 'f' ? '<defs>' + [['u', 33, 41.4], ['m', 41.4, 47.6], ['l', 47.6, 56]].map(([b, y0, y1]) => '<clipPath id="' + id + b + '"><rect x="0" y="' + y0 + '" width="100" height="' + (y1 - y0 - 0.9) + '"/></clipPath>').join('') + '</defs>' : '';
  let extra = '';
  if (opts.mode === 'joints') extra = [[33, 34], [40.6, 96], [42.8, 141], [27.8, 74]].map(([x, y]) => '<circle class="jz" cx="' + x + '" cy="' + y + '" r="3"/><circle class="jz" cx="' + (100 - x) + '" cy="' + y + '" r="3"/>').join('') + '<circle class="jz" cx="50" cy="29" r="2.6"/>';
  if (opts.mode === 'heart') extra = '<path class="hz" d="M50 56 C44 51.5 40.5 48 40.5 44.4 C40.5 41.6 42.6 39.6 45.2 39.6 C47.2 39.6 48.8 40.8 50 42.6 C51.2 40.8 52.8 39.6 54.8 39.6 C57.4 39.6 59.5 41.6 59.5 44.4 C59.5 48 56 51.5 50 56 Z"/>';
  const head = view === 'b' ? '<path class="nz" d="M44.6 25 L55.4 25 L55.4 30 L44.6 30 Z"/>' : '<path class="nz" d="M45 25 L55 25 L55 31.6 L45 31.6 Z"/>';
  return '<svg class="fig' + (opts.cls ? ' ' + opts.cls : '') + '" viewBox="18 3 64 186" aria-hidden="true">' + clips + '<circle class="nz" cx="50" cy="15" r="9.6"/>' + head + half(false) + half(true) + extra + '</svg>';
}
// the figure(s) for a group: its views, its parts lit (sel = the chosen part, the others soft)
export function groupFigure(g, sel, cls) {
  if (g === 'cardio') return figure('f', {}, { mode: 'heart', cls });
  if (g === 'full') return figure('f', {}, { mode: 'all', cls });
  if (g === 'mobility') return figure('f', {}, { mode: 'joints', cls });
  const all = (SUBS[g] || []).map(s => g + '.' + s);
  const H = sel ? hotFor([g + '.' + sel], all) : hotFor(all);
  return viewsOf(g).split('').map(v => figure(v, H[v], { cls })).join('');
}
// the figure for a training day: every part its exercises train (own part strong)
export function dayFigure(exs, cls) {
  const keys = []; exs.forEach(x => { if (x && x.grp && REG[x.grp + '.' + x.sub]) keys.push(x.grp + '.' + x.sub); });
  const H = hotFor(keys); const back = Object.keys(H.b).length > 0, front = Object.keys(H.f).length > 0 || !back;
  return (front ? figure('f', H.f, { cls }) : '') + (back ? figure('b', H.b, { cls }) : '');
}
// "Chest · Triceps" for a list of exercises (in order of how often they appear)
export function groupsLine(exs) {
  const n = {}; exs.forEach(x => { if (x && x.grp) n[x.grp] = (n[x.grp] || 0) + 1; });
  return Object.keys(n).sort((a, b) => n[b] - n[a] || GROUP_KEYS.indexOf(a) - GROUP_KEYS.indexOf(b)).map(groupName).join(' · ');
}
export { esc };
